EPixelFormat getAstcFormat(int blockSize, int variant) {
    constexpr EPixelFormat formats[3][5] = {
        {EPixelFormat::PF_ASTC_4x4, EPixelFormat::PF_ASTC_6x6, EPixelFormat::PF_ASTC_8x8, EPixelFormat::PF_ASTC_10x10, EPixelFormat::PF_ASTC_12x12},
        {EPixelFormat::PF_ASTC_4x4_HDR, EPixelFormat::PF_ASTC_6x6_HDR, EPixelFormat::PF_ASTC_8x8_HDR, EPixelFormat::PF_ASTC_10x10_HDR, EPixelFormat::PF_ASTC_12x12_HDR},
        {EPixelFormat::PF_ASTC_4x4_NORM_RG, EPixelFormat::PF_ASTC_6x6_NORM_RG, EPixelFormat::PF_ASTC_8x8_NORM_RG, EPixelFormat::PF_ASTC_10x10_NORM_RG,
         EPixelFormat::PF_ASTC_12x12_NORM_RG},
    };
    constexpr int blockSizes[5] = {4, 6, 8, 10, 12};
    return formats[variant][std::ranges::find(blockSizes, blockSize) - std::begin(blockSizes)];
}

bool matchesPixels(const DecodedImage& image, std::span<const int> expected, int tolerance) {
    for (std::size_t i = 0; i < image.rgba.size(); i++)
        if (std::abs(static_cast<int>(std::lround(image.rgba[i] * 255.0f)) - expected[i]) > tolerance)
            return false;
    return true;
}

bool matchesAstcBlock(const AstcCase& testCase, int variant, std::span<const int> expected) {
    const std::span<const std::byte> data(reinterpret_cast<const std::byte*>(testCase.block.data()), testCase.block.size());
    const auto decoded = decodePixels(PixelLayout{getAstcFormat(testCase.blockSize, variant), testCase.blockSize, testCase.blockSize, 1}, data);
    return CHECK(decoded.has_value()) && matchesPixels(*decoded, expected, 1);
}

